-- Hand-written (P), C249.3: the audit log's retention, owned by the role that runs this migration and
-- run with its rights (SECURITY DEFINER), so the runtime role needs no delete on audit_logs. It deletes
-- at most p_limit entries of the environment older than its audit-log-retention-days (absent: none),
-- never under the 30-day minimum, measured from the caller's time; their address index rows cascade.
CREATE FUNCTION "openverify_delete_expired_audit_logs"(p_environment_id text, p_now timestamptz, p_limit integer)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_days integer;
  v_deleted integer;
BEGIN
  SELECT CASE WHEN jsonb_typeof(e.settings -> 'audit-log-retention-days') = 'number'
              THEN floor((e.settings ->> 'audit-log-retention-days')::numeric)::integer END
    INTO v_days
    FROM public.environments e
   WHERE e.id = p_environment_id;
  IF v_days IS NULL OR v_days < 1 OR p_now IS NULL OR p_limit IS NULL OR p_limit < 1 THEN
    RETURN 0;
  END IF;
  v_days := greatest(v_days, 30);
  DELETE FROM public.audit_logs a
   WHERE a.id IN (SELECT o.id FROM public.audit_logs o
                   WHERE o.environment_id = p_environment_id
                     AND o.created_at < p_now - make_interval(days => v_days)
                   ORDER BY o.created_at, o.id
                   LIMIT p_limit);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;
--> statement-breakpoint
-- Hand-written (P), C249.3: the watchlist names' pending GIN lists moved into their indexes after a
-- source's sync (owner decision 1 after 6B), with the owner's rights; platform-ops moves the call.
CREATE FUNCTION "openverify_gin_clean_pending_lists"(p_source_id text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF p_source_id IS NULL THEN
    RETURN;
  END IF;
  PERFORM gin_clean_pending_list('public.watchlist_names_keys_idx'::regclass);
  PERFORM gin_clean_pending_list('public.watchlist_names_normalised_trgm_idx'::regclass);
END;
$$;
--> statement-breakpoint
-- Hand-written (P), C249.3 (V05): a delete of an audit entry or a share policy is refused unless the
-- current role owns the table (the migration role, also inside the SECURITY DEFINER function) or the
-- delete comes from a cascade (the environment's deletion, pg_trigger_depth() > 1). No session
-- setting bypasses it.
CREATE FUNCTION "openverify_refuse_delete"()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN OLD;
  END IF;
  IF current_user = (SELECT r.rolname FROM pg_catalog.pg_class c
                       JOIN pg_catalog.pg_roles r ON r.oid = c.relowner
                      WHERE c.oid = TG_RELID) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'rows of % are deleted only by their retention or with their environment', TG_TABLE_NAME
    USING ERRCODE = '42501';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "openverify_audit_logs_delete_guard" BEFORE DELETE ON "audit_logs"
  FOR EACH ROW EXECUTE FUNCTION "openverify_refuse_delete"();
--> statement-breakpoint
CREATE TRIGGER "openverify_connect_share_policies_delete_guard" BEFORE DELETE ON "connect_share_policies"
  FOR EACH ROW EXECUTE FUNCTION "openverify_refuse_delete"();
